        // @BeanMapping( ignoreByDefault = true )
        if ( mappingOptions.getBeanMapping() != null && mappingOptions.getBeanMapping().isIgnoredByDefault() ) {
            mappingOptions.applyIgnoreAll( method, typeFactory, mappingContext.getMessager() );
        }

